cat > /etc/nginx/sites-available/default <<'ANTRIEB_NGINX_EOF'
server {
    listen 5660 default_server;
    listen [::]:5660 default_server;
    server_name _;

    root /var/www/html;
    index index.html;

    location = / {
        try_files /index.html =404;
    }
}
ANTRIEB_NGINX_EOF
printf '%s\n' "$NODE_NAME" > /var/www/html/index.html
printf 'configured=%s\n' "$NODE_NAME"

